/* طبخة اليوم — واجهة PWA محلية بالكامل */
'use strict';
const STORE_KEY='tabkhet-alyom-state-v1';
const CATALOG_VERSION=3;
const categories=[...new Set(['الكل','فراخ','لحوم','أسماك','خضار','بقوليات','مكرونة وأرز','فطار وعشاء','شوربات','حلويات',...(window.RECIPE_SPEC_CATEGORIES||[])])];
const units=['جم','كجم','مل','لتر','قطعة','بيضة','فص','ملعقة','ملعقة صغيرة','ملعقة كبيرة','كوب','علبة','عبوة','رشة'];
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const FOOD_AVOID_OPTIONS=[
{key:'meat',label:'اللحوم والدواجن والسمك (نباتي)',terms:['فراخ','دجاج','لحم','لحمة','لحوم','كفتة','سجق','بسطرمة','كبدة','سمك','جمبري','روبيان','تونة','سردين','كابوريا','كاليماري','محار','سبيط']},
{key:'gluten',label:'القمح والجلوتين',terms:['قمح','دقيق','طحين','مكرونة','مكرونه','خبز','برغل','شعير','فريك','سميد','لسان عصفور','عيش','بقسماط']},
{key:'dairy',label:'الألبان ومشتقاتها',terms:['لبن','حليب','جبن','جبنة','زبدة','سمن','سمنة','قشطة','كريمة','زبادي','موزاريلا']},
{key:'egg',label:'البيض',terms:['بيض']},
{key:'nuts',label:'المكسرات والفول السوداني',terms:['مكسرات','لوز','جوز','عين الجمل','بندق','فستق','كاجو','فول سوداني','سوداني']},
{key:'seafood',label:'السمك والمأكولات البحرية',terms:['سمك','جمبري','روبيان','تونة','سردين','كابوريا','كاليماري','محار']},
{key:'soy',label:'الصويا',terms:['صويا','صوص صويا']},{key:'sesame',label:'السمسم والطحينة',terms:['سمسم','طحينة']},{key:'mustard',label:'الخردل والمستردة',terms:['خردل','مستردة']}];
function recipeBlockedByFoodPreferences(r){const filters=state.settings?.foodFilters||{},text=ingredientKey([r.name,...(r.ingredientsText||[]),(r.ingredients||[]).map(x=>x.name)].join(' '));return FOOD_AVOID_OPTIONS.some(o=>filters[o.key]&&o.terms.some(t=>text.includes(ingredientKey(t))))}
function parseQuantity(value){return Number(String(value??'').trim().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/٫/g,'.'))}
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>`i-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
let state=loadState(), activeNav='home', recipeFilter='الكل', currentRecipeId=null, moreView='menu', deferredInstall=null, toastTimer, stepTimerInterval=null, stepTimerDeadline=0, stepTimerLabel='';
function sameSeedContent(a,b){const core=r=>JSON.stringify([r.name||'',r.category||'',r.tag||'',r.emoji||'',Number(r.servings)||0,Number(r.prep)||0,Number(r.cook)||0,(r.ingredients||[]).map(x=>[x.name,Number(x.qty),x.unit]),r.steps||[],r.notes||'']);return core(a)===core(b)}
function loadState(){const defaults={pantry:[],shopping:[],history:[],weeklyPlan:[],budgets:{daily:0,weekly:0},settings:{largeText:false,lowAlerts:true,foodFilters:{}},catalogVersion:CATALOG_VERSION};try{const s=JSON.parse(localStorage.getItem(STORE_KEY)||'null');if(s&&Array.isArray(s.recipes)){const latest=new Map(seedRecipes.map(r=>[r.id,r])),legacyRows=typeof window!=='undefined'&&Array.isArray(window.LEGACY_SEED_RECIPES)?window.LEGACY_SEED_RECIPES:[],legacy=new Map(legacyRows.map(r=>[r.id,r])),needsMigration=(Number(s.catalogVersion)||1)<CATALOG_VERSION;let refreshed=false;const current=s.recipes.map(local=>{const replacement=latest.get(local.id),baseline=legacy.get(local.id);if(needsMigration&&replacement&&baseline&&sameSeedContent(local,baseline)){refreshed=true;return {...clone(replacement),favorite:!!local.favorite,...(local._servings?{_servings:local._servings}:{})}}return local});const existing=new Set(current.map(r=>r.id)),additions=seedRecipes.filter(r=>!existing.has(r.id)).map(clone),merged={...defaults,...s,catalogVersion:CATALOG_VERSION,recipes:[...current,...additions]};if(additions.length||refreshed||Number(s.catalogVersion)!==CATALOG_VERSION){try{localStorage.setItem(STORE_KEY,JSON.stringify(merged))}catch(e){console.warn('تعذّر حفظ تحديث الوصفات في التخزين المحلي',e)}}return merged}}catch(e){console.warn('تعذر قراءة البيانات المحلية',e)}return {recipes:clone(seedRecipes),...defaults}}
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));updateBadge();return true}catch(e){console.warn('تعذر حفظ بيانات التطبيق',e);toast('تعذر الحفظ على هذا الجهاز؛ قد تكون مساحة التخزين ممتلئة. صدّري نسخة احتياطية أو أفرغي مساحة.');return false}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function updateBadge(){const n=state.shopping.filter(x=>!x.checked).length;const b=$('#shoppingBadge');b.textContent=n;b.classList.toggle('hidden',n===0)}
function money(n){return Number.isFinite(n)?`${new Intl.NumberFormat('ar-EG',{maximumFractionDigits:2}).format(n)} جنيه`:'غير محسوبة'}
function qty(n){return new Intl.NumberFormat('ar-EG',{maximumFractionDigits:2}).format(Number(n)||0)}
function fmtDate(iso){try{return new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium'}).format(new Date(iso))}catch{return ''}}function pantryExpiryDays(p){if(!p?.expiresOn)return null;const now=new Date();now.setHours(0,0,0,0);const d=new Date(`${p.expiresOn}T00:00:00`);return Number.isNaN(d.getTime())?null:Math.floor((d-now)/86400000)}function pantryExpiryLabel(p){const n=pantryExpiryDays(p);if(n===null)return '';if(n<0)return `منتهي الصلاحية منذ ${qty(Math.abs(n))} يوم`;if(n===0)return 'تنتهي صلاحيته اليوم';if(n<=3)return `ينتهي خلال ${qty(n)} يوم`;return `الصلاحية ${fmtDate(p.expiresOn)}`}
function recipeById(rid){return state.recipes.find(r=>r.id===rid)}
function ingredientKey(name){let key=String(name??'').trim().toLowerCase().replace(/[\u064B-\u065F\u0670ـ]/g,'').replace(/[أإآٱ]/g,'ا').replace(/\s+/g,' ');if(['فراخ','دجاج','دجاجة'].includes(key))return 'دجاج';if(['لبن','حليب'].includes(key))return 'لبن';return key}
function pantryByName(name){const key=ingredientKey(name);return state.pantry.find(p=>ingredientKey(p.name)===key)}
function toBase(value,unit){if(unit==='كجم')return [value*1000,'weight'];if(unit==='جم')return [value,'weight'];if(unit==='لتر')return [value*1000,'volume'];if(unit==='مل')return [value,'volume'];return [value,unit]}
function convert(value,from,to){if(from===to)return Number(value);const [v,a]=toBase(Number(value),from),[,b]=toBase(1,to);if(a!==b)return null;const [factor]=toBase(1,to);return v/factor}
function convertedAvailable(p,unit){return p?convert(Number(p.qty)||0,p.unit,unit):0}
function getCost(r,servings=r.servings){let known=0,unknown=[],lines=[];const mult=Number(servings||r.servings)/Math.max(1,Number(r.servings)||1);for(const ing of r.ingredients||[]){const amount=Number(ing.qty)*mult,p=pantryByName(ing.name);let lineCost=null;if(p&&Number.isFinite(Number(p.unitPrice))&&p.unitPrice>0){const inP=convert(amount,ing.unit,p.unit);if(inP!==null)lineCost=inP*Number(p.unitPrice)}if(lineCost===null)unknown.push(ing.name);else known+=lineCost;lines.push({ing,amount,p,lineCost})}return {known,unknown,complete:unknown.length===0,lines}}
function shortage(r,servings=r.servings){return (r.ingredients||[]).map(ing=>{const required=Number(ing.qty)*Number(servings||r.servings)/Math.max(1,Number(r.servings)||1),p=pantryByName(ing.name),have=p?convertedAvailable(p,ing.unit):0;return {...ing,required,have:have===null?0:have,missing:Math.max(0,required-(have||0)),compatible:!p||have!==null}})}
function pantryMatch(r,servings=r.servings){const lines=shortage(r,servings);const score=lines.length?lines.reduce((sum,x)=>sum+Math.min(1,Math.max(0,x.have/Math.max(x.required,1e-9))),0)/lines.length:0;return {score,missing:lines.filter(x=>x.missing>1e-9).length,ready:lines.length-lines.filter(x=>x.missing>1e-9).length}}
function countLow(){return state.pantry.filter(p=>Number(p.low)>0&&Number(p.qty)<=Number(p.low)).length}
function todaySpend(){const d=new Date().toDateString();return state.history.filter(x=>new Date(x.date).toDateString()===d).reduce((s,x)=>s+(Number(x.cost)||0),0)}
function weekSpend(){const now=new Date(),from=new Date(now);from.setDate(now.getDate()-6);from.setHours(0,0,0,0);return state.history.filter(x=>new Date(x.date)>=from).reduce((s,x)=>s+(Number(x.cost)||0),0)}
function navTo(page){activeNav=page;currentRecipeId=null;render()}
function render(){updateBadge();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav===activeNav));document.body.classList.toggle('large-text',!!state.settings.largeText);if(currentRecipeId){renderDetail(currentRecipeId);return}const root=$('#screen');if(activeNav==='home')root.innerHTML=homeHTML();else if(activeNav==='recipes')root.innerHTML=recipesHTML();else if(activeNav==='pantry')root.innerHTML=pantryHTML();else if(activeNav==='shopping')root.innerHTML=shoppingHTML();else root.innerHTML=moreHTML();root.scrollTop=0}
function recipeTimeSummary(r){const prep=r.prepLabel||`${qty(r.prep||0)} دقيقة`,cook=r.cookLabel||`${qty(r.cook||0)} دقيقة`;return `تحضير ${esc(prep)} · طهي ${esc(cook)}`}
function recipeCard(r){const c=getCost(r);return `<article class="recipe-card" data-action="open-recipe" data-id="${esc(r.id)}"><div class="recipe-art">${esc(r.emoji||'🍲')}</div><div class="recipe-info"><h3>${esc(r.name)}</h3><p>${esc(r.tag||r.category)} · ${recipeTimeSummary(r)} · ${qty(r.servings)} أفراد</p><div class="recipe-cost">${c.complete?money(c.known):`التكلفة المعروفة ${money(c.known)}${c.unknown.length?' · أسعار ناقصة':''}`}</div></div><button class="heart-btn ${r.favorite?'liked':''}" data-action="favorite" data-id="${esc(r.id)}" aria-label="${r.favorite?'إزالة من':'إضافة إلى'} المفضلة">${r.favorite?'♥':'♡'}</button></article>`}
function homeHTML(){const eligible=state.recipes.filter(r=>!recipeBlockedByFoodPreferences(r)),today=eligible.filter(r=>!state.history.some(h=>h.recipeId===r.id&&new Date(h.date).toDateString()===new Date().toDateString())),suggestion=today[0]||eligible[0]||null,available=state.pantry.length?eligible.map(r=>({r,match:pantryMatch(r)})).filter(x=>x.match.score>0).sort((a,b)=>b.match.score-a.match.score||a.match.missing-b.match.missing||((Number(a.r.prep)||0)+(Number(a.r.cook)||0))-((Number(b.r.prep)||0)+(Number(b.r.cook)||0))).slice(0,3):[];const budget=Number(state.budgets.daily)||0,spent=todaySpend(),remain=Math.max(0,budget-spent);const hero=suggestion?`<section class="hero-card"><div class="hero-top"><span class="pill">اقتراح النهارده · ${esc(suggestion.tag||'من وصفات البيت')}</span><span class="hero-emoji">${esc(suggestion.emoji||'🍲')}</span></div><h2>${esc(suggestion.name)}</h2><div class="hero-meta"><span>◷ ${recipeTimeSummary(suggestion)}</span><span>♧ ${qty(suggestion.servings)} أفراد</span><span>◎ ${getCost(suggestion).complete?money(getCost(suggestion).known):'سجلي الأسعار للحساب'}</span></div><div class="hero-actions"><button class="btn btn-light" data-action="open-recipe" data-id="${esc(suggestion.id)}">شوفي الوصفة</button><button class="btn btn-ghost" data-action="random">🎲 اختاريلي أكلة</button></div></section>`:`<div class="empty-state"><span>🥗</span><h3>مفيش وصفة مطابقة للفلاتر</h3><p>راجعي فلاتر المكونات من الإعدادات عشان تظهر اقتراحات مناسبة.</p><button class="btn small" data-action="more-view" data-view="settings">مراجعة الفلاتر</button></div>`;return `<div class="home-greeting"><div><p class="eyebrow">صباح الخير</p><h1 class="page-title">هنطبخ إيه النهارده؟</h1><p class="page-subtitle">اختاري أكلة تليق بيومك، والباقي علينا.</p></div><div class="greeting-mark">🌿</div></div>${hero}<div class="quick-row"><button class="quick-tile" data-nav="recipes"><span class="q-icon">📖</span><strong>دوري على وصفة</strong><small>${qty(eligible.length)} وصفة متاحة حسب فلاترك</small></button><button class="quick-tile" data-nav="pantry"><span class="q-icon">🧺</span><strong>إيه الموجود عندي؟</strong><small>${qty(state.pantry.length)} مكونات مسجلة</small></button></div><div class="section-head"><h2>ممكن تعملي إيه بالموجود؟</h2><button class="btn outline small" data-nav="recipes">كل الوصفات</button></div>${available.length?`<div class="recipe-list">${available.map(x=>`<div><div class="inline-note" style="margin:0 0 8px"><strong>${Math.round(x.match.score*100)}٪</strong> من المقادير متوفر${x.match.missing?` · ${qty(x.match.missing)} مكونات ناقصة`:' — كل المقادير متوفرة'}</div>${recipeCard(x.r)}</div>`).join('')}</div>`:`<div class="empty-state"><span>🧺</span><h3>${state.pantry.length?'مفيش وصفات من الفلاتر الحالية تعتمد على مخزونك':'سجّلي شوية مكونات'}</h3><p>هنا هنقترح وصفات على قد الموجود في مطبخك.</p><button class="btn small" data-nav="pantry">ضيفي مكونات</button></div>`}<div class="section-head"><h2>لمحة سريعة</h2></div><div class="stats-grid"><div class="stat-card"><span class="stat-icon">🥫</span><strong>${qty(state.pantry.length)}</strong><small>مكوّن في مطبخي</small></div><div class="stat-card"><span class="stat-icon">🛒</span><strong>${qty(state.shopping.filter(x=>!x.checked).length)}</strong><small>حاجة في المشتريات</small></div><div class="stat-card"><span class="stat-icon">💰</span><strong>${budget?money(remain):'—'}</strong><small>باقي ميزانية اليوم</small></div></div>${state.history.length?`<div class="section-head"><h2>طبختي مؤخرًا</h2><button class="btn outline small" data-action="more-view" data-view="history">السجل</button></div><div class="card"><strong>${esc(state.history[0].recipeName)}</strong><p class="page-subtitle">اتطبخت ${fmtDate(state.history[0].date)} · ${qty(state.history[0].servings)} أفراد</p><div class="recipe-cost">${state.history[0].cost===null?'التكلفة غير مكتملة':money(state.history[0].cost)}</div></div>`:''}`}

function recipesHTML(){const list=state.recipes.filter(r=>(recipeFilter==='الكل'||r.category===recipeFilter)&&!recipeBlockedByFoodPreferences(r));return `<p class="eyebrow">أكلات البيت في مكان واحد</p><h1 class="page-title">الوصفات</h1><p class="page-subtitle">دوري بالاسم أو بمكوّن، واختاري على مزاجك.</p><div class="search-wrap"><input id="recipeSearch" type="search" placeholder="دوري على أكلة أو مكوّن…" autocomplete="off"></div><div class="chip-row">${categories.map(c=>`<button class="chip ${recipeFilter===c?'active':''}" data-action="filter" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="btn-row" style="margin:4px 0 14px"><button class="btn small" data-action="add-recipe">＋ أضيفي وصفة</button><button class="btn secondary small" data-action="random">🎲 اختاريلي أكلة</button><button class="btn outline small" data-action="favorites">♥ المفضلة</button></div><p id="recipeCount" class="eyebrow">${list.length} وصفة</p><div id="recipeResults" class="recipe-list">${list.map(recipeCard).join('')}</div>`}
function filteredRecipes(){const q=($('#recipeSearch')?.value||'').trim().toLowerCase();const list=state.recipes.filter(r=>!recipeBlockedByFoodPreferences(r)&&(recipeFilter==='الكل'||r.category===recipeFilter)&&(!q||r.name.toLowerCase().includes(q)||r.category.toLowerCase().includes(q)||((r.ingredients||[]).some(i=>i.name.toLowerCase().includes(q))||(r.ingredientsText||[]).some(i=>i.toLowerCase().includes(q)))));return list}
function updateRecipeResults(){const list=filteredRecipes(),target=$('#recipeResults'),count=$('#recipeCount');if(target)target.innerHTML=list.length?list.map(recipeCard).join(''):`<div class="empty-state"><span>🔎</span><h3>ملقيناش اللي بتدوري عليه</h3><p>جرّبي كلمة تانية أو اختاري تصنيفًا مختلفًا.</p></div>`;if(count)count.textContent=`${qty(list.length)} وصفة`}
function pantryHTML(){const q=($('#pantrySearch')?.value||'').trim().toLowerCase(),expiryOnly=!!state.ui?.expiryOnly;let list=state.pantry.filter(p=>!q||p.name.toLowerCase().includes(q));if(expiryOnly)list=list.filter(p=>{const n=pantryExpiryDays(p);return n!==null&&n<=7});const due=state.pantry.filter(p=>{const n=pantryExpiryDays(p);return n!==null&&n<=7}).length;return `<p class="eyebrow">كل حاجة في مكانها</p><h1 class="page-title">مطبخي</h1><p class="page-subtitle">سجّلي الكميات والأسعار وتواريخ الصلاحية بنفسك.</p><div class="search-wrap"><input id="pantrySearch" type="search" placeholder="دوري على مكوّن…" autocomplete="off"></div><div class="btn-row"><button class="btn" data-action="add-pantry">＋ إضافة مكوّن</button><button class="btn secondary" data-action="low-only">${state.ui?.lowOnly?'عرض الكل':'قرب يخلص'} · ${countLow()}</button><button class="btn outline" data-action="expiry-only">${expiryOnly?'كل الصلاحيات':'منتهية أو قريبة'} · ${qty(due)}</button></div><div id="pantryResults" class="card" style="margin-top:14px;padding:5px 14px">${pantryRows(list)}</div><div class="inline-note" style="margin-top:12px">التحويل التلقائي متاح بين جم/كجم ومل/لتر فقط. الوحدات الأخرى لازم تكون متطابقة.</div>`}
function pantryRows(list){if(state.ui?.lowOnly)list=list.filter(p=>Number(p.qty)<=Number(p.low||0));return list.length?list.map(p=>{const days=pantryExpiryDays(p),expiry=pantryExpiryLabel(p),expiryClass=days!==null&&days<0?'low-text':days!==null&&days<=3?'expiry-soon':'';return `<div class="inventory-row"><div class="row-main"><strong>${esc(p.name)}</strong><small>${p.low>0&&Number(p.qty)<=Number(p.low)?'<span class="low-text">قرب يخلص · </span>':''}${p.priceUpdated?`السعر اتحدّث ${fmtDate(p.priceUpdated)}`:'السعر غير مسجل'}${expiry?` · <span class="${expiryClass}">${esc(expiry)}</span>`:''}</small></div><div class="row-amount">${qty(p.qty)} ${esc(p.unit)}<br><small>${p.unitPrice>0?`${money(p.unitPrice)} / ${esc(p.unit)}`:'—'}</small></div><div class="mini-actions"><button class="icon-button" data-action="edit-pantry" data-id="${esc(p.id)}" aria-label="تعديل">✎</button><button class="icon-button" data-action="delete-pantry" data-id="${esc(p.id)}" aria-label="حذف">×</button></div></div>`}).join(''):`<div class="empty-state" style="border:0"><span>🧺</span><h3>${state.ui?.lowOnly?'مفيش مكونات قربت تخلص':state.ui?.expiryOnly?'مفيش مكونات منتهية أو صلاحيتها خلال 7 أيام':'مطبخك لسه فاضي'}</h3><p>${state.ui?.expiryOnly?'أضيفي تاريخ الصلاحية عند تسجيل المكونات.':'ضيفي مكوناتك وأسعارها عشان نحسب التكلفة والنواقص.'}</p></div>`}
function shoppingHTML(){const pending=state.shopping.filter(x=>!x.checked),done=state.shopping.filter(x=>x.checked),total=state.shopping.reduce((s,x)=>s+(Number(x.estimated)||0),0);return `<p class="eyebrow">كل اللي ناقصك في مشوار واحد</p><h1 class="page-title">قائمة المشتريات</h1><p class="page-subtitle">النواقص من الوصفات بتتجمع هنا، وتقدري تعدّليها في أي وقت.</p><div class="btn-row" style="margin:15px 0"><button class="btn" data-action="add-shopping">＋ أضيفي حاجة</button><button class="btn secondary" data-action="add-shopping-to-pantry" ${done.length?'':'disabled'}>إضافة المشتريات للمخزون</button></div><div class="card budget-card" style="margin-bottom:13px"><div class="budget-row"><div><small class="muted">التكلفة التقديرية للعناصر اللي لها سعر</small><strong class="budget-value">${money(total)}</strong></div><span>🧾</span></div></div><div class="card" style="padding:6px 14px"><div class="section-head" style="margin:10px 0 4px"><h2>مطلوب شراؤه (${pending.length})</h2></div>${pending.length?pending.map(shopRow).join(''):`<div class="empty-state" style="border:0"><span>🛍️</span><h3>القائمة فاضية</h3><p>من تفاصيل أي وصفة اضغطي «ضيفي الناقص للمشتريات».</p></div>`}${done.length?`<div class="divider"></div><div class="section-head" style="margin:10px 0 4px"><h2>اتشرى (${done.length})</h2><button class="btn outline small" data-action="clear-done">مسح</button></div>${done.map(shopRow).join('')}`:''}</div><p class="inline-note" style="margin-top:12px">المبلغ تقديري حسب الأسعار اللي سجلتيها. سعر العبوة في السوق ممكن يختلف عن تكلفة الكمية المطلوبة.</p>`}
function shopRow(x){return `<div class="shopping-row ${x.checked?'done':''}"><input class="checkbox" type="checkbox" ${x.checked?'checked':''} data-action="toggle-shopping" data-id="${esc(x.id)}" aria-label="تم الشراء"><div class="row-main"><strong>${esc(x.name)}</strong><small>${qty(x.qty)} ${esc(x.unit)}${x.source?` · ${esc(x.source)}`:''}</small></div><div class="row-amount">${x.estimated?money(x.estimated):'—'}</div><div class="mini-actions"><button class="icon-button" data-action="edit-shopping" data-id="${esc(x.id)}" aria-label="تعديل">✎</button><button class="icon-button" data-action="delete-shopping" data-id="${esc(x.id)}" aria-label="حذف">×</button></div></div>`}
function moreHTML(){if(moreView==='planner')return plannerHTML();if(moreView==='favorites')return `<button class="btn outline small" data-action="more-view" data-view="menu">← المزيد</button><p class="eyebrow" style="margin-top:16px">الأكلات اللي بتحبيها</p><h1 class="page-title">المفضلة</h1><div class="recipe-list" style="margin-top:16px">${state.recipes.filter(r=>r.favorite&&!recipeBlockedByFoodPreferences(r)).map(recipeCard).join('')||`<div class="empty-state"><span>♡</span><h3>لسه مفيش مفضلة</h3><p>اضغطي على القلب جنب أي وصفة عشان تلاقيها هنا.</p></div>`}</div>`;if(moreView==='history')return historyHTML();if(moreView==='settings')return settingsHTML();return `<p class="eyebrow">كل حاجة زيادة هتلاقيها هنا</p><h1 class="page-title">المزيد</h1><p class="page-subtitle">مفضلاتك وخطة الوجبات وسجل الطبخ والإعدادات والنسخة الاحتياطية.</p><div class="more-grid" style="margin-top:19px"><button class="more-link" data-action="more-view" data-view="favorites"><span class="more-icon">♥</span><span><strong>المفضلة</strong><small>${state.recipes.filter(r=>r.favorite).length} وصفة محفوظة</small></span><span class="arrow">‹</span></button><button class="more-link" data-action="more-view" data-view="history"><span class="more-icon">🕘</span><span><strong>سجل الطبخ</strong><small>${state.history.length} أكلة اتسجلت</small></span><span class="arrow">‹</span></button><button class="more-link" data-action="more-view" data-view="planner"><span class="more-icon">📅</span><span><strong>خطة الوجبات</strong><small>${(state.weeklyPlan||[]).length} وجبة مخططة</small></span><span class="arrow">‹</span></button><button class="more-link" data-action="more-view" data-view="settings"><span class="more-icon">⚙</span><span><strong>الإعدادات والبيانات</strong><small>الميزانية · النسخة الاحتياطية · حجم الخط</small></span><span class="arrow">‹</span></button></div><div class="inline-note" style="margin-top:16px">بياناتك محفوظة على الجهاز في المتصفح. اعملي نسخة احتياطية قبل حذف التطبيق أو بيانات المتصفح.</div>`}
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function planDateLabel(date){try{return new Intl.DateTimeFormat('ar-EG',{weekday:'long',day:'numeric',month:'long'}).format(new Date(`${date}T12:00:00`))}catch{return date}}function plannerHTML(){const plan=(state.weeklyPlan||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.meal.localeCompare(b.meal));const options=state.recipes.filter(r=>!recipeBlockedByFoodPreferences(r)).slice().sort((a,b)=>a.name.localeCompare(b.name,'ar')).map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');return `<button class="btn outline small" data-action="more-view" data-view="menu">← المزيد</button><p class="eyebrow" style="margin-top:16px">رتّبي أكلات الأيام الجاية</p><h1 class="page-title">خطة الوجبات</h1><p class="page-subtitle">اختاري اليوم والوجبة والوصفة؛ هتفضل الخطة محفوظة على الجهاز.</p><form id="planForm" class="card" style="margin-top:14px"><div class="form-grid"><div class="field"><label>اليوم</label><input type="date" name="date" value="${todayISO()}" required></div><div class="field"><label>الوجبة</label><select name="meal"><option>إفطار</option><option selected>غداء</option><option>عشاء</option></select></div><div class="field full"><label>الوصفة</label><select name="recipeId" required>${options}</select></div><div class="field"><label>عدد الأفراد</label><input name="servings" type="number" min="1" value="4" required></div></div><button class="btn full" type="submit">إضافة للخطة</button></form><div class="section-head"><h2>الوجبات المخططة</h2><button class="btn secondary small" data-action="plan-shopping" ${plan.length?'':'disabled'}>أضيفي النواقص للمشتريات</button></div><div class="card" style="padding:7px 14px">${plan.length?plan.map(x=>{const r=recipeById(x.recipeId);return r?`<div class="inventory-row"><div class="row-main"><strong>${esc(planDateLabel(x.date))} · ${esc(x.meal)}</strong><small>${esc(r.name)} · ${qty(x.servings)} أفراد</small></div><button class="icon-button" data-action="plan-remove" data-id="${esc(x.id)}" aria-label="حذف من الخطة">×</button></div>`:''}).join('')||'<p class="page-subtitle">الوصفات المرتبطة بالخطة لم تعد موجودة.</p>':`<div class="empty-state" style="border:0"><span>📅</span><h3>الخطة لسه فاضية</h3><p>ضيفي أكلة ليوم مناسب، وبعدها اجمعي النواقص للمشتريات.</p></div>`}</div><p class="page-subtitle" style="margin-top:10px">قائمة المشتريات تجمع الكميات الرقمية الناقصة فقط؛ الكميات التقريبية والاختيارات تراجعينها يدويًا.</p>`}
function historyHTML(){const list=state.history;return `<button class="btn outline small" data-action="more-view" data-view="menu">← المزيد</button><p class="eyebrow" style="margin-top:16px">أكلات سجلتي إنها اتطبخت</p><h1 class="page-title">سجل الطبخ</h1><div class="card" style="margin-top:15px;padding:7px 14px">${list.length?list.map(h=>`<div class="inventory-row"><div class="recipe-art" style="width:45px;height:45px;flex-basis:45px;font-size:24px">${esc(h.emoji||'🍲')}</div><div class="row-main"><strong>${esc(h.recipeName)}</strong><small>${fmtDate(h.date)} · ${qty(h.servings)} أفراد</small></div><div class="row-amount">${h.cost!==null&&Number.isFinite(Number(h.cost))?money(Number(h.cost)):'التكلفة غير مكتملة'}</div></div>`).join(''):`<div class="empty-state" style="border:0"><span>🍽️</span><h3>لسه مفيش أكلات في السجل</h3><p>بعد ما تخلصي وصفة، اضغطي «تم الطبخ» وسجّليها.</p></div>`}</div>`}
function settingsHTML(){const b=state.budgets||{};return `<button class="btn outline small" data-action="more-view" data-view="menu">← المزيد</button><p class="eyebrow" style="margin-top:16px">تظبيط التطبيق على بيتك</p><h1 class="page-title">الإعدادات والبيانات</h1><section class="card" style="margin-top:15px"><h2 style="font-size:16px;margin:0 0 5px">ميزانية الأكل</h2><p class="page-subtitle">مقارنة تقريبية بتكلفة الوصفات اللي سجلتيها، مش بالمبلغ الفعلي في السوق.</p><div class="form-grid" style="margin-top:13px"><div class="field"><label for="dailyBudget">ميزانية اليوم (جنيه)</label><input id="dailyBudget" type="number" min="0" step="1" value="${Number(b.daily)||0}"></div><div class="field"><label for="weeklyBudget">ميزانية الأسبوع (جنيه)</label><input id="weeklyBudget" type="number" min="0" step="1" value="${Number(b.weekly)||0}"></div></div><button class="btn small" data-action="save-budget">حفظ الميزانية</button></section><section class="card more-section"><h2 style="font-size:16px;margin:0 0 9px">تفضيلات العرض</h2><label class="toggle-line"><span>تكبير الخط</span><input type="checkbox" id="largeText" ${state.settings.largeText?'checked':''}></label><label class="toggle-line"><span>إظهار تنبيهات المخزون القليل</span><input type="checkbox" id="lowAlerts" ${state.settings.lowAlerts?'checked':''}></label></section><section class="card more-section"><h2 style="font-size:16px;margin:0 0 6px">تصفية مكونات وحساسيات</h2><p class="page-subtitle">تخفي الوصفات التي يظهر فيها المكوّن ضمن النص المسجل.</p>${FOOD_AVOID_OPTIONS.map(o=>`<label class="toggle-line"><span>${esc(o.label)}</span><input type="checkbox" data-food-filter="${esc(o.key)}" ${(state.settings.foodFilters||{})[o.key]?'checked':''}></label>`).join('')}<p class="warning-text">فلتر إرشادي يعتمد على الكلمات المكتوبة، وليس ضمانًا لغياب مسببات الحساسية أو التلوث التبادلي. راجعي دائمًا المقادير وملصقات المنتجات.</p></section><section class="card more-section"><h2 style="font-size:16px;margin:0 0 6px">حماية بياناتك</h2><p class="page-subtitle">النسخة الاحتياطية ملف على جهازك؛ انقليه لمكان آمن عشان ما يضيع لو اتمسحت بيانات المتصفح.</p><div class="btn-row" style="margin-top:13px"><button class="btn" data-action="backup">حفظ نسخة احتياطية</button><button class="btn secondary" data-action="restore">استعادة نسخة</button></div><p class="warning-text">الاستعادة هتستبدل البيانات الحالية. قبلها هننزّل نسخة تلقائية من الحالة الحالية.</p></section><section class="card more-section"><h2 style="font-size:16px;margin:0 0 6px">بيانات التطبيق</h2><p class="page-subtitle">طبخة اليوم · نسخة PWA محلية · ${state.recipes.length} وصفة</p><div class="divider"></div><button class="btn danger small" data-action="reset">مسح كل البيانات وإعادة البداية</button></section>`}
function matchStockIngredient(text,lines){const direct=lines.find(x=>x.sourceText===text);if(direct)return direct;const key=ingredientKey(text).replace(/فراخ/g,'دجاج');if(!/^(?:(?:نحو|حوالي|تقريبا)\s*)?(?:[0-9٠-٩۰-۹]+(?:[.٫/][0-9٠-٩۰-۹]+)?(?:\s*[–—-]\s*[0-9٠-٩۰-۹]+)?|نصف|ربع)(?:\s|$)/.test(key))return null;return lines.find(x=>key.includes(ingredientKey(x.name)))}
function ingredientStatusText(line){const have=Math.min(Number(line.have)||0,Number(line.required)||0);return line.missing>0?`موجود ${qty(have)} ${esc(line.unit)} · ناقص ${qty(line.missing)} ${esc(line.unit)}`:`متوفر ${qty(line.required)} ${esc(line.unit)}`}
function scaledIngredientText(text,matched,servings,baseServings){if(ingredientKey(text).includes('حسب الرغبة')||Number(servings)===Number(baseServings))return text;const re=/^(\s*(?:(?:نحو|حوالي|تقريبا|تقريبًا)\s*)?)([0-9٠-٩۰-۹]+(?:[٫./][0-9٠-٩۰-۹]+)?)(?=\s)/;return String(text).replace(re,(_,prefix,token)=>{const n=token.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/٫/g,'.');const value=n.includes('/')?Number(n.split('/')[0])/Number(n.split('/')[1]):Number(n);return `${prefix}${qty(value*Number(servings)/Math.max(1,Number(baseServings)))}`})}
function recipeIngredientsSection(r,lines,servings){const base=Number(r.servings)||1;const rows=r.ingredientsText?.length?r.ingredientsText.map(text=>{const matched=matchStockIngredient(text,lines),shown=scaledIngredientText(text,matched,servings,base);return `<li class="recipe-ingredient-row"><span>${esc(shown)}</span>${matched?`<small class="${matched.missing>0?'missing':'available'}">${ingredientStatusText(matched)}</small>`:''}</li>`}).join(''):lines.map(x=>`<li class="recipe-ingredient-row"><span>${qty(x.required)} ${esc(x.unit)} ${esc(x.name)}</span><small class="${x.missing>0?'missing':'available'}">${ingredientStatusText(x)}</small></li>`).join('');return `<section class="card recipe-ingredients-card" style="margin-top:13px"><div class="section-head" style="margin:0 0 6px"><h2>المقادير</h2></div><p class="page-subtitle">كل المقادير هنا. «موجود» هو ما سجلته في مطبخك، و«ناقص» هو ما تحتاجه الوصفة ولا يوجد لديك؛ والحالة تظهر بجانب المقادير ذات الكمية القابلة للحساب فقط.${Number(servings)!==base?' تم تعديل الكميات الرقمية تناسبيًا؛ قرّبي الوحدات العَدَدية عمليًا عند الحاجة.':''}</p><ul class="recipe-ingredients-list">${rows||'<li>لم تُسجل مقادير بعد.</li>'}</ul></section>`}
function recipeMetadataSection(r){const items=[{field:'tools',title:'الأدوات',value:r.tools,type:'list'},{field:'success',title:'علامات النجاح',value:r.success},{field:'mistakes',title:'أخطاء شائعة',value:r.mistakes},{field:'serving',title:'التقديم',value:r.serving},{field:'storage',title:'الحفظ',value:r.storage}].filter(x=>Array.isArray(x.value)?x.value.length:String(x.value||'').trim());if(!items.length)return '';return `<section class="card recipe-metadata-card" style="margin-top:12px"><div class="section-head" style="margin:0 0 3px"><h2>تفاصيل الوصفة</h2></div><div class="recipe-metadata-list">${items.map(x=>`<div class="recipe-metadata-item"><h3>${esc(x.title)}</h3>${r.generatedFields?.includes(x.field)?'<small class="recipe-suggestion-note">اقتراح تحريري لاستكمال البطاقة، وليس نصًا من ملف الوصفات.</small>':''}${x.type==='list'?`<ul>${x.value.map(y=>`<li>${esc(y)}</li>`).join('')}</ul>`:`<p>${esc(x.value)}</p>`}</div>`).join('')}</div></section>`}
function renderDetail(rid){const r=recipeById(rid);if(!r){currentRecipeId=null;render();return}const servings=Number(r._servings)||Number(r.servings)||1,cost=getCost(r,servings),lines=shortage(r,servings);$('#screen').innerHTML=`<button class="btn outline small" data-action="back">← رجوع للوصفات</button><div class="detail-hero" style="margin-top:14px"><div class="detail-emoji">${esc(r.emoji||'🍲')}</div><div><h1>${esc(r.name)}</h1><p>${esc(r.category)}${r.difficulty?` · ${esc(r.difficulty)}`:''}<br>${recipeTimeSummary(r)}</p></div></div><div class="card" style="margin-top:12px"><div class="budget-row"><strong>عدد الأفراد</strong><div class="stepper"><button data-action="servings" data-delta="-1">−</button><strong>${qty(servings)}</strong><button data-action="servings" data-delta="1">＋</button></div></div></div><div class="btn-row" style="margin-top:11px"><button class="btn secondary" data-action="favorite" data-id="${esc(r.id)}">${r.favorite?'♥ في المفضلة':'♡ أضيفي للمفضلة'}</button><button class="btn" data-action="add-missing" data-id="${esc(r.id)}">🛒 ضيفي الناقص للمشتريات</button></div>${recipeIngredientsSection(r,lines,servings)}<section class="card" style="margin-top:12px"><div class="section-head" style="margin:0 0 10px"><h2>طريقة التحضير · ${(r.steps||[]).length} خطوات</h2></div><ol class="steps-list">${(r.steps||[]).map((step,i)=>`<li><span class="step-num">${i+1}</span><div class="step-row-content"><label class="step-check"><input type="checkbox"><span>${esc(step)}</span></label><button class="btn outline small step-timer-button" data-action="step-timer" data-id="${esc(r.id)}" data-step="${i+1}">⏱ مؤقّت</button></div></li>`).join('')}</ol><p id="stepTimerStatus" class="inline-note" style="${stepTimerDeadline>Date.now()?'':'display:none;'}">${stepTimerDeadline>Date.now()?esc(timerRemainingText()):''}</p>${r.notes?`<div class="inline-note" style="margin-top:12px">ملاحظة: ${esc(r.notes)}</div>`:''}${r.sourceUrl?`<a class="source-link" href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">مصدر الوصفة: ${esc(r.sourceCreator||'شاهدي الفيديو على YouTube')}</a>`:''}</section>${recipeMetadataSection(r)}<section class="card" style="margin-top:12px"><div class="section-head" style="margin:0 0 10px"><h2>التكلفة التقديرية</h2></div><div class="cost-summary"><div class="cost-box"><small>التكلفة المعروفة</small><strong>${money(cost.known)}</strong></div><div class="cost-box"><small>تكلفة الفرد</small><strong>${money(cost.known/Math.max(1,servings))}</strong></div><div class="cost-box"><small>سعر ناقص</small><strong>${cost.unknown.length?`${cost.unknown.length} مكونات`:'لا يوجد'}</strong></div><div class="cost-box"><small>المكونات الناقصة</small><strong>${lines.filter(x=>x.missing>0).length}</strong></div></div>${cost.unknown.length?`<p class="warning-text">التكلفة غير مكتملة؛ السعر غير مسجل لـ: ${cost.unknown.map(esc).join('، ')}. مش هنخمن أسعار.</p>`:''}</section><div class="btn-row" style="margin:13px 0"><button class="btn" data-action="cook" data-id="${esc(r.id)}">🍽️ تم الطبخ</button><button class="btn outline" data-action="edit-recipe" data-id="${esc(r.id)}">تعديل الوصفة</button></div>${r.source==='custom'?`<button class="btn danger full" data-action="delete-recipe" data-id="${esc(r.id)}">حذف الوصفة</button>`:''}`;$('#screen').scrollTop=0}
function timerRemainingText(){const seconds=Math.max(0,Math.ceil((stepTimerDeadline-Date.now())/1000)),m=Math.floor(seconds/60),sec=seconds%60;return `مؤقّت ${stepTimerLabel} · متبقّي ${qty(m)}:${String(sec).padStart(2,'0')}`}function updateStepTimer(){const el=document.querySelector('#stepTimerStatus');if(stepTimerDeadline>Date.now()){if(el){el.style.display='block';el.textContent=timerRemainingText()}return}if(stepTimerInterval){clearInterval(stepTimerInterval);stepTimerInterval=null}if(stepTimerDeadline){stepTimerDeadline=0;if(el){el.style.display='block';el.textContent=`انتهى مؤقّت ${stepTimerLabel}`}if(navigator.vibrate)navigator.vibrate([180,100,180]);toast(`انتهى مؤقّت ${stepTimerLabel}`)}}function stepTimerForm(r,step){modal(`مؤقّت الخطوة ${step}`,`<p class="page-subtitle">اكتبي المدة اللي تناسبك بالدقائق؛ مش هنخمّن الوقت من نص الخطوة. بدء مؤقّت جديد يستبدل المؤقّت النشط، ويعمل التنبيه ما دام التطبيق مفتوحًا.</p><form id="timerForm"><input type="hidden" name="recipeId" value="${esc(r.id)}"><input type="hidden" name="step" value="${step}"><div class="field"><label>المدة بالدقائق</label><input type="number" name="minutes" min="1" max="360" step="1" required autofocus></div><div class="form-actions"><button class="btn" type="submit">ابدأ المؤقّت</button><button class="btn secondary" type="button" data-action="close-modal">إلغاء</button></div></form>`)}function startStepTimer(r,step,minutes){if(stepTimerInterval)clearInterval(stepTimerInterval);stepTimerLabel=`${r.name} · الخطوة ${step}`;stepTimerDeadline=Date.now()+minutes*60000;closeModal();updateStepTimer();stepTimerInterval=setInterval(updateStepTimer,1000);toast(`بدأ مؤقّت ${qty(minutes)} دقيقة`)}
function modal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close-btn" data-action="close-modal" aria-label="إغلاق">×</button></div>${body}</div></div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function unitOptions(selected){return units.map(u=>`<option ${u===selected?'selected':''}>${u}</option>`).join('')}
function ingredientEditorRow(x={}){return `<div class="ingredient-editor-row"><div class="field"><label>اسم المكوّن</label><input name="ingredientName" maxlength="55" value="${esc(x.name||'')}" placeholder="مثال: بطاطس"></div><div class="field"><label>الكمية</label><input name="ingredientQty" type="number" min="0.001" step="any" value="${x.qty??''}" placeholder="مثال: ٢"></div><div class="field"><label>الوحدة</label><select name="ingredientUnit">${unitOptions(x.unit||'جم')}</select></div><button class="ingredient-remove" type="button" data-action="remove-ingredient-row" aria-label="حذف المكوّن">×</button></div>`}
function recipeForm(r){const editing=!!r;const ingredientRows=(r?.ingredients?.length?r.ingredients:[{}]).map(ingredientEditorRow).join('');const fullIngredients=(r?.ingredientsText?.length?r.ingredientsText:(r?.ingredients||[]).map(x=>`${qty(x.qty)} ${x.unit} ${x.name}`)).join('\n');const lines=(value)=>Array.isArray(value)?value.join('\n'):String(value||'');modal(editing?'تعديل الوصفة':'أضيفي وصفة جديدة',`<form id="recipeForm"><input type="hidden" name="id" value="${esc(r?.id||'')}"><div class="form-grid"><div class="field full"><label>اسم الأكلة</label><input name="name" required maxlength="70" value="${esc(r?.name||'')}" placeholder="مثال: بطاطس ماما بالصلصة"></div><div class="field"><label>التصنيف</label><select name="category">${categories.filter(x=>x!=='الكل').map(c=>`<option ${c===r?.category?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>رمز للأكلة</label><select name="emoji">${['🍲','🍗','🥗','🍝','🥘','🍳','🥔','🐟','🫘','🍰','🥣','🥬'].map(x=>`<option ${x===(r?.emoji||'🍲')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>الصعوبة</label><input name="difficulty" value="${esc(r?.difficulty||'')}" placeholder="سهلة / متوسطة"></div><div class="field"><label>عدد الأفراد الأساسي</label><input name="servings" type="number" min="1" value="${Number(r?.servings)||4}" required></div><div class="field"><label>التحضير (دقائق للحساب)</label><input name="prep" type="number" min="0" value="${Number(r?.prep)||0}"></div><div class="field"><label>وقت التحضير المعروض</label><input name="prepLabel" value="${esc(r?.prepLabel||`${Number(r?.prep)||0} دقيقة`)}" placeholder="مثال: 20–30 دقيقة"></div><div class="field"><label>الطهي (دقائق للحساب)</label><input name="cook" type="number" min="0" value="${Number(r?.cook)||0}"></div><div class="field"><label>وقت الطهي المعروض</label><input name="cookLabel" value="${esc(r?.cookLabel||`${Number(r?.cook)||0} دقيقة`)}" placeholder="مثال: 45–60 دقيقة"></div><div class="field full"><label>مقادير الوصفة كاملة (سطر لكل مكوّن)</label><textarea name="ingredientsText" rows="7" required placeholder="1 كوب أرز\nملح حسب الرغبة">${esc(fullIngredients)}</textarea><small>هذه القائمة الكاملة التي تظهر في الوصفة؛ لا تحذفي منها العناصر التي لا تملك كمية رقمية.</small></div><div class="field full"><label>المقادير الرقمية لحساب المخزون (اختياري)</label><div id="ingredientRows" class="ingredient-editor-list">${ingredientRows}</div><button class="btn outline small" type="button" data-action="add-ingredient-row">＋ أضيفي مكوّنًا قابلًا للحساب</button><small>استخدميها فقط للكميات المحددة رقمياً. النطاقات و«حسب الرغبة» تبقى في القائمة الكاملة أعلاه.</small></div><div class="field full"><label>الأدوات (سطر لكل أداة)</label><textarea name="tools" rows="3">${esc(lines(r?.tools))}</textarea></div><div class="field full"><label>طريقة التحضير (سطر لكل خطوة)</label><textarea name="steps" rows="7" required placeholder="قطّعي المكونات…\nاطهيها على نار هادئة…">${esc((r?.steps||[]).join('\n'))}</textarea></div><div class="field full"><label>علامات النجاح</label><textarea name="success" rows="2">${esc(r?.success||'')}</textarea></div><div class="field full"><label>أخطاء شائعة</label><textarea name="mistakes" rows="2">${esc(r?.mistakes||'')}</textarea></div><div class="field full"><label>التقديم</label><textarea name="serving" rows="2">${esc(r?.serving||'')}</textarea></div><div class="field full"><label>الحفظ</label><textarea name="storage" rows="2">${esc(r?.storage||'')}</textarea></div><div class="field full"><label>ملاحظة تقديرية أو تحريرية</label><textarea name="editorialNote" rows="2">${esc(r?.editorialNote||'')}</textarea></div><div class="field full"><label>ملاحظات خاصة أو مصدر (اختياري)</label><input name="notes" value="${esc(r?.notes||'')}"></div></div><div class="form-actions"><button class="btn" type="submit">حفظ الوصفة</button><button class="btn secondary" type="button" data-action="close-modal">إلغاء</button></div></form>`)}
function pantryForm(p){const edit=!!p;modal(edit?'تعديل مكوّن':'إضافة مكوّن للمطبخ',`<form id="pantryForm"><input type="hidden" name="id" value="${esc(p?.id||'')}"><div class="form-grid"><div class="field full"><label>اسم المكوّن</label><input name="name" required maxlength="55" value="${esc(p?.name||'')}" placeholder="مثال: أرز"></div><div class="field"><label>الكمية الموجودة</label><input name="qty" type="number" min="0" step="any" required value="${Number(p?.qty)||''}"></div><div class="field"><label>الوحدة</label><select name="unit">${unitOptions(p?.unit||'جم')}</select></div><div class="field"><label>حد التنبيه</label><input name="low" type="number" min="0" step="any" value="${Number(p?.low)||0}"></div><div class="field"><label>السعر (اختياري)</label><input name="totalPrice" type="number" min="0" step="any" value="${p?.unitPrice?Number(p.unitPrice)*Number(p.priceBasisQty||1):''}" placeholder="إجمالي السعر"></div><div class="field"><label>الكمية التي يغطيها السعر</label><input name="priceBasisQty" type="number" min="0.001" step="any" value="${Number(p?.priceBasisQty)||1}"></div><div class="field"><label>وحدة السعر</label><select name="priceBasisUnit">${unitOptions(p?.priceBasisUnit||p?.unit||'جم')}</select></div><div class="field full"><label>تاريخ الصلاحية (اختياري)</label><input name="expiresOn" type="date" value="${esc(p?.expiresOn||'')}"></div></div><p class="inline-note">لو سجلتي السعر، اكتبي إجمالي سعر كمية معروفة. التطبيق يقسم السعر على الكمية لحساب تكلفة الوصفات.</p><div class="form-actions"><button class="btn" type="submit">حفظ المكوّن</button><button class="btn secondary" type="button" data-action="close-modal">إلغاء</button></div></form>`)}
function shoppingForm(x){modal(x?'تعديل عنصر':'إضافة للمشتريات',`<form id="shoppingForm"><input type="hidden" name="id" value="${esc(x?.id||'')}"><div class="form-grid"><div class="field full"><label>اسم الحاجة</label><input name="name" required value="${esc(x?.name||'')}" placeholder="مثال: لبن"></div><div class="field"><label>الكمية</label><input name="qty" type="number" step="any" min="0.01" value="${Number(x?.qty)||1}" required></div><div class="field"><label>الوحدة</label><select name="unit">${unitOptions(x?.unit||'قطعة')}</select></div><div class="field full"><label>السعر التقديري (اختياري)</label><input name="estimated" type="number" step="any" min="0" value="${Number(x?.estimated)||''}"></div></div><div class="form-actions"><button class="btn" type="submit">حفظ</button><button class="btn secondary" type="button" data-action="close-modal">إلغاء</button></div></form>`)}
function addMissing(r){const missing=shortage(r,Number(r._servings)||r.servings).filter(x=>x.missing>0);let added=0;for(const x of missing){const found=state.shopping.find(s=>s.name.toLowerCase()===x.name.toLowerCase()&&s.unit===x.unit&&!s.checked);if(found){found.qty=Number(found.qty)+x.missing;found.source=found.source?`${found.source}، ${r.name}`:r.name;const p=pantryByName(x.name);if(p?.unitPrice){const conv=convert(found.qty,x.unit,p.unit);found.estimated=conv===null?0:conv*p.unitPrice}}else{const p=pantryByName(x.name),conv=p?.unitPrice?convert(x.missing,x.unit,p.unit):null;state.shopping.push({id:id(),name:x.name,qty:x.missing,unit:x.unit,estimated:conv===null?0:(p?.unitPrice||0)*conv,checked:false,source:r.name})}added++}save();toast(added?`اتضاف ${qty(added)} مكوّن للقائمة`:'كل المقادير متوفرة عندك');}
function addRecipeToHistory(r,servings,used){const key=id(),cost=getCost(r,servings);for(const u of used){const p=pantryByName(u.name);if(!p)continue;const inP=convert(Number(u.qty),u.unit,p.unit);if(inP!==null)p.qty=Math.max(0,Number(p.qty)-inP)}state.history.unshift({id:key,recipeId:r.id,recipeName:r.name,emoji:r.emoji,date:new Date().toISOString(),servings:Number(servings),used:clone(used),cost:cost.complete?cost.known:null});save();closeModal();currentRecipeId=null;activeNav='more';moreView='history';render();toast('اتسجلت الأكلة واتخصم الموجود مرة واحدة')}
function cookForm(r){const servings=Number(r._servings)||r.servings,lines=shortage(r,servings);modal('راجعي الكميات قبل الخصم',`<p class="page-subtitle">المخزون مش هيتخصم غير بعد تأكيدك. عدّلي الكمية لو استخدمتي مقدارًا مختلفًا.</p><form id="cookForm"><input type="hidden" name="recipeId" value="${esc(r.id)}"><input type="hidden" name="servings" value="${servings}"><div class="card" style="padding:7px 12px;margin:12px 0">${lines.map((x,i)=>`<div class="ingredient-line"><strong>${esc(x.name)}</strong><span><input name="used-${i}" type="number" min="0" step="any" value="${qty(x.required)}" style="width:82px;border:1px solid var(--line);border-radius:9px;padding:6px" data-unit="${esc(x.unit)}" data-name="${esc(x.name)}"></span><small>${esc(x.unit)} · موجود ${qty(x.have)}</small></div>`).join('')}</div><div class="form-actions"><button class="btn" type="submit">تأكيد الطبخ والخصم</button><button class="btn secondary" type="button" data-action="close-modal">لسه</button></div></form>`)}
function exportBackup(automatic=false){const payload={app:'TabkhetElYom',version:1,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`TabkhetElYom_Backup${automatic?'_قبل_الاستعادة':''}_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);if(!automatic)toast('النسخة الاحتياطية اتحفظت في جهازك')}
function beginRestore(){if(confirm('هننزّل نسخة من بياناتك الحالية أولًا، وبعدها تختاري ملف الاستعادة. تكملي؟')){$('#backupFile').click()}}
function restoreBackup(file){const reader=new FileReader();reader.onload=()=>{try{const raw=JSON.parse(reader.result);const incoming=raw.state||raw;if(!Array.isArray(incoming.recipes)||!Array.isArray(incoming.pantry)||!Array.isArray(incoming.shopping)||!Array.isArray(incoming.history))throw new Error('invalid');exportBackup(true);state={...state,...incoming,budgets:{daily:0,weekly:0,...incoming.budgets},settings:{largeText:false,lowAlerts:true,foodFilters:{},...incoming.settings}};save();closeModal();currentRecipeId=null;activeNav='home';moreView='menu';render();toast('تمت استعادة بياناتك')}catch(e){toast('الملف مش نسخة احتياطية صالحة للتطبيق')}};reader.readAsText(file)}
function randomRecipe(){const eligible=state.recipes.filter(r=>!recipeBlockedByFoodPreferences(r));if(!eligible.length)return toast('مافيش وصفات تطابق فلاتر المكونات الحالية');const recent=new Set(state.history.slice(0,3).map(h=>h.recipeId));const options=eligible.filter(r=>!recent.has(r.id));const r=(options.length?options:eligible)[Math.floor(Math.random()*(options.length||eligible.length))];if(r){currentRecipeId=r.id;activeNav='recipes';render();toast('اقتراح جديد من وصفات البيت')}}
function handleClick(e){const nav=e.target.closest('[data-nav]');if(nav){navTo(nav.dataset.nav);return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,rid=el.dataset.id;if(a==='add-ingredient-row'){const root=$('#ingredientRows');if(root){const holder=document.createElement('div');holder.innerHTML=ingredientEditorRow();root.append(holder.firstElementChild);root.lastElementChild.querySelector('[name="ingredientName"]').focus()}return}if(a==='remove-ingredient-row'){const row=el.closest('.ingredient-editor-row'),root=$('#ingredientRows');if(row&&root){if(root.children.length>1)row.remove();else{row.querySelector('[name="ingredientName"]').value='';row.querySelector('[name="ingredientQty"]').value='';row.querySelector('[name="ingredientUnit"]').value='جم'}}return}
 if(a==='open-recipe'){currentRecipeId=rid;activeNav='recipes';render();return}if(a==='back'){currentRecipeId=null;render();return}if(a==='filter'){recipeFilter=el.dataset.filter;render();return}if(a==='random'){randomRecipe();return}if(a==='favorite'){const r=recipeById(rid||currentRecipeId);if(r){r.favorite=!r.favorite;save();render();toast(r.favorite?'اتضافت للمفضلة':'اتشالت من المفضلة')}return}if(a==='favorites'){activeNav='more';moreView='favorites';render();return}if(a==='more-view'){moreView=el.dataset.view||'menu';activeNav='more';render();return}if(a==='plan-remove'){state.weeklyPlan=(state.weeklyPlan||[]).filter(x=>x.id!==rid);save();render();return}if(a==='plan-shopping'){addPlanToShopping();return}if(a==='add-recipe'){recipeForm(null);return}if(a==='edit-recipe'){const r=recipeById(rid);if(r)recipeForm(r);return}if(a==='delete-recipe'){const r=recipeById(rid);if(r&&confirm(`تحذفي وصفة «${r.name}»؟`)){state.recipes=state.recipes.filter(x=>x.id!==rid);save();currentRecipeId=null;render();toast('اتحذفت الوصفة')}return}if(a==='servings'){const r=recipeById(currentRecipeId);if(r){r._servings=Math.max(1,(Number(r._servings)||r.servings)+Number(el.dataset.delta));renderDetail(currentRecipeId)}return}if(a==='add-missing'){const r=recipeById(rid);if(r)addMissing(r);return}if(a==='cook'){const r=recipeById(rid);if(r)cookForm(r);return}if(a==='step-timer'){const r=recipeById(rid);if(r)stepTimerForm(r,Number(el.dataset.step)||1);return}if(a==='add-pantry'){pantryForm(null);return}if(a==='edit-pantry'){const p=state.pantry.find(x=>x.id===rid);if(p)pantryForm(p);return}if(a==='delete-pantry'){const p=state.pantry.find(x=>x.id===rid);if(p&&confirm(`تحذفي «${p.name}» من المخزون؟`)){state.pantry=state.pantry.filter(x=>x.id!==rid);save();render();toast('اتحذف المكوّن')}return}if(a==='low-only'){state.ui={...state.ui,lowOnly:!state.ui?.lowOnly};render();return}if(a==='expiry-only'){state.ui={...state.ui,expiryOnly:!state.ui?.expiryOnly};render();return}if(a==='add-shopping'){shoppingForm(null);return}if(a==='edit-shopping'){const x=state.shopping.find(s=>s.id===rid);if(x)shoppingForm(x);return}if(a==='delete-shopping'){state.shopping=state.shopping.filter(x=>x.id!==rid);save();render();return}if(a==='toggle-shopping')return;if(a==='clear-done'){state.shopping=state.shopping.filter(x=>!x.checked);save();render();toast('اتمسحت العناصر المشتراة من القائمة');return}if(a==='add-shopping-to-pantry'){addBoughtToPantry();return}if(a==='backup'){exportBackup();return}if(a==='restore'){beginRestore();return}if(a==='reset'){if(confirm('هتمسحي كل الوصفات والمخزون والأسعار والمشتريات والسجل من الجهاز. متأكدة؟')){localStorage.removeItem(STORE_KEY);state={recipes:clone(seedRecipes),pantry:[],shopping:[],history:[],weeklyPlan:[],budgets:{daily:0,weekly:0},settings:{largeText:false,lowAlerts:true,foodFilters:{}},catalogVersion:CATALOG_VERSION};currentRecipeId=null;activeNav='home';moreView='menu';render();toast('رجعنا للبداية')}return}if(a==='save-budget'){state.budgets={daily:Math.max(0,Number($('#dailyBudget').value)||0),weekly:Math.max(0,Number($('#weeklyBudget').value)||0)};save();render();toast('اتحفظت الميزانية');return}if(a==='close-modal'){closeModal();return}if(a==='backdrop'&&e.target===el){closeModal();return}}
document.addEventListener('click',handleClick,true);
document.addEventListener('input',e=>{if(e.target.id==='recipeSearch')updateRecipeResults();if(e.target.id==='pantrySearch'){const list=state.pantry.filter(p=>p.name.toLowerCase().includes(e.target.value.trim().toLowerCase()));const root=$('#pantryResults');if(root)root.innerHTML=pantryRows(list)}},true);
document.addEventListener('change',e=>{if(e.target.matches('.checkbox[data-action="toggle-shopping"]')){const x=state.shopping.find(s=>s.id===e.target.dataset.id);if(x){x.checked=e.target.checked;save();render()}return}if(e.target.id==='largeText'){state.settings.largeText=e.target.checked;save();document.body.classList.toggle('large-text',e.target.checked)}if(e.target.id==='lowAlerts'){state.settings.lowAlerts=e.target.checked;save()}if(e.target.matches('[data-food-filter]')){state.settings.foodFilters={...(state.settings.foodFilters||{}),[e.target.dataset.foodFilter]:e.target.checked};save();if(activeNav==='recipes')updateRecipeResults()}},true);
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);
 if(f.getAttribute('id')==='recipeForm'){const rawIngredients=[...f.querySelectorAll('.ingredient-editor-row')].map(row=>{const name=row.querySelector('[name="ingredientName"]').value.trim(),amount=row.querySelector('[name="ingredientQty"]').value.trim(),unit=row.querySelector('[name="ingredientUnit"]').value;return {name,qty:parseQuantity(amount),unit,hasAny:!!(name||amount)}});const ingredientsText=String(fd.get('ingredientsText')||'').split('\n').map(x=>x.trim()).filter(Boolean);if((!rawIngredients.some(x=>x.hasAny)&&!ingredientsText.length)||rawIngredients.some(x=>x.hasAny&&(!x.name||!Number.isFinite(x.qty)||x.qty<=0||!units.includes(x.unit))))return toast('أضيفي مكوّنًا واحدًا على الأقل، واكتبي اسمًا وكمية ووحدة صحيحة لكل مقدار قابل للحساب.');const ingredients=rawIngredients.filter(x=>x.hasAny).map(({name,qty,unit})=>({name,qty,unit}));const steps=String(fd.get('steps')).split('\n').map(x=>x.trim()).filter(Boolean);if(!steps.length)return toast('اكتبي خطوة واحدة على الأقل');const rid=fd.get('id'),old=rid?recipeById(rid):null;const item={...(old||{}),id:rid||id(),name:String(fd.get('name')).trim(),category:fd.get('category'),emoji:fd.get('emoji'),servings:parseQuantity(fd.get('servings'))||4,prep:parseQuantity(fd.get('prep'))||0,cook:parseQuantity(fd.get('cook'))||0,ingredients,steps,ingredientsText,tools:String(fd.get('tools')||'').split('\n').map(x=>x.trim()).filter(Boolean),difficulty:String(fd.get('difficulty')||''),prepLabel:String(fd.get('prepLabel')||`${Number(fd.get('prep'))||0} دقيقة`),cookLabel:String(fd.get('cookLabel')||`${Number(fd.get('cook'))||0} دقيقة`),success:String(fd.get('success')||''),mistakes:String(fd.get('mistakes')||''),serving:String(fd.get('serving')||''),storage:String(fd.get('storage')||''),editorialNote:String(fd.get('editorialNote')||''),notes:String(fd.get('notes')||''),source:old?.source||'custom',sourceUrl:old?.sourceUrl||'',sourceCreator:old?.sourceCreator||'',favorite:old?.favorite||false,tag:old?.tag||'من وصفات البيت'};const previous=state.recipes;state.recipes=old?state.recipes.map(x=>x.id===old.id?item:x):[item,...state.recipes];if(!save()){state.recipes=previous;return}closeModal();currentRecipeId=item.id;activeNav='recipes';render();toast(old?'اتحدّثت الوصفة':'اتحفظت وصفتك على هذا الجهاز')}
 if(f.getAttribute('id')==='timerForm'){const r=recipeById(String(fd.get('recipeId')||'')),minutes=Math.floor(Number(fd.get('minutes'))),step=Math.max(1,Number(fd.get('step'))||1);if(!r||!Number.isFinite(minutes)||minutes<1||minutes>360)return toast('اكتبي مدة من دقيقة إلى 360 دقيقة');startStepTimer(r,step,minutes)}
 if(f.getAttribute('id')==='planForm'){const recipe=recipeById(String(fd.get('recipeId')||'')),date=String(fd.get('date')||''),meal=String(fd.get('meal')||'غداء'),servings=Math.max(1,parseQuantity(fd.get('servings'))||Number(recipe?.servings)||4);if(!recipe||!/^\d{4}-\d{2}-\d{2}$/.test(date))return toast('اختاري يومًا ووصفة صالحة');state.weeklyPlan=Array.isArray(state.weeklyPlan)?state.weeklyPlan:[];state.weeklyPlan.push({id:id(),date,meal,recipeId:recipe.id,servings});save();moreView='planner';activeNav='more';render();toast('اتضافت الوجبة للخطة')}
 if(f.getAttribute('id')==='pantryForm'){const name=String(fd.get('name')).trim(),unit=fd.get('unit'),q=Number(fd.get('qty')),price=Number(fd.get('totalPrice')),basis=Number(fd.get('priceBasisQty'))||1,basisUnit=fd.get('priceBasisUnit');let p=fd.get('id')?state.pantry.find(x=>x.id===fd.get('id')):pantryByName(name);if(!p){p={id:id(),name,qty:q,unit,low:Number(fd.get('low'))||0,unitPrice:null,priceBasisQty:1};state.pantry.push(p)}else{p.name=name;const converted=convert(q,unit,p.unit);if(p.unit!==unit&&converted===null)return toast('الوحدة مختلفة ولا يمكن تحويلها؛ سجّلي المكوّن كوحدة منفصلة.');p.qty=converted===null?q:converted;p.low=Number(fd.get('low'))||0}p.expiresOn=String(fd.get('expiresOn')||'');if(price>0){const per=price/basis,conv=convert(1,basisUnit,p.unit);if(conv===null)return toast('وحدة سعر الشراء غير متوافقة مع وحدة المخزون');p.unitPrice=per/conv;p.priceBasisQty=basis;p.priceBasisUnit=basisUnit;p.priceUpdated=new Date().toISOString()}else if(!p.unitPrice){p.unitPrice=null}save();closeModal();render();toast('اتحفظ المكوّن والسعر')}
 if(f.getAttribute('id')==='shoppingForm'){const name=String(fd.get('name')).trim(),obj={id:fd.get('id')||id(),name,qty:Number(fd.get('qty')),unit:fd.get('unit'),estimated:Number(fd.get('estimated'))||0,checked:false,source:'إضافة يدوية'},old=state.shopping.find(x=>x.id===obj.id);if(old)Object.assign(old,obj);else state.shopping.push(obj);save();closeModal();render();toast('اتحفظت الحاجة في المشتريات')}
 if(f.getAttribute('id')==='cookForm'){const r=recipeById(fd.get('recipeId'));if(!r)return toast('الوصفة مش موجودة');const servings=Number(fd.get('servings')),used=(r.ingredients||[]).map((ing,i)=>({name:ing.name,unit:ing.unit,qty:Math.max(0,Number(fd.get(`used-${i}`))||0)}));addRecipeToHistory(r,servings,used)}
},true);
function addPlanToShopping(){const entries=state.weeklyPlan||[];if(!entries.length)return toast('ضيفي وجبات للخطة الأول');const grouped=new Map();for(const x of entries){const r=recipeById(x.recipeId);if(!r)continue;for(const item of shortage(r,Number(x.servings)||Number(r.servings)||1)){if(item.missing<=0)continue;const key=`${ingredientKey(item.name)}|${item.unit}`;const current=grouped.get(key)||{name:item.name,qty:0,unit:item.unit};current.qty+=item.missing;grouped.set(key,current)}}if(!grouped.size)return toast('كل المقادير الرقمية المطلوبة موجودة في مطبخك');state.shopping=state.shopping.filter(x=>x.source!=='خطة الوجبات');for(const x of grouped.values())state.shopping.push({id:id(),...x,estimated:0,checked:false,source:'خطة الوجبات'});save();activeNav='shopping';render();toast(`اتضاف ${qty(grouped.size)} مكونات ناقصة من خطة الوجبات`)}
function addBoughtToPantry(){const bought=state.shopping.filter(x=>x.checked);if(!bought.length)return toast('علّمي على الحاجات اللي اتشرت الأول');for(const x of bought){let p=pantryByName(x.name);if(!p){p={id:id(),name:x.name,qty:Number(x.qty),unit:x.unit,low:0,unitPrice:null,priceBasisQty:1};state.pantry.push(p);continue}const add=convert(Number(x.qty),x.unit,p.unit);if(add===null){state.pantry.push({id:id(),name:x.name,qty:Number(x.qty),unit:x.unit,low:0,unitPrice:null,priceBasisQty:1})}else p.qty=Number(p.qty)+add}state.shopping=state.shopping.filter(x=>!x.checked);save();render();toast('اتضافت الكميات المشتراة للمخزون')}
$('#backupFile').addEventListener('change',e=>{const f=e.target.files?.[0];if(f){if(confirm('الاستعادة هتستبدل كل بيانات التطبيق الحالية. نكمل؟'))restoreBackup(f);e.target.value=''}});
window.addEventListener('online',()=>updateConnection());window.addEventListener('offline',()=>updateConnection());function updateConnection(){const el=$('#connectionState');el.classList.toggle('offline',!navigator.onLine);el.querySelector('span').textContent=navigator.onLine?'محفوظ عندك':'دون اتصال'}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').addEventListener('click',async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#installBtn').classList.add('hidden')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(e=>console.warn('Service worker',e)));
if(state.settings.largeText)document.body.classList.add('large-text');updateConnection();render();
